from typing import Final

import pytest

BITS: Final[int] = 8
MASK: Final[int] = (1 << BITS) - 1


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits to low.

    x is in 0..255 and k is in 0..7. The result is in 0..255.
    """
    x &= MASK
    k &= BITS - 1
    return ((x << k) | (x >> (BITS - k))) & MASK


def test_rotl8_zero_shift_is_identity() -> None:
    assert rotl8(0b10110010, 0) == 0b10110010


def test_rotl8_single_bit_wraps() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011


def test_rotl8_high_bit_moves_to_low() -> None:
    assert rotl8(0x80, 1) == 0x01


def test_rotl8_seven_shift_of_one() -> None:
    assert rotl8(0x01, 7) == 0x80


def test_rotl8_nibble_swap() -> None:
    assert rotl8(0x12, 4) == 0x21


def test_rotl8_all_ones_is_fixed() -> None:
    assert rotl8(MASK, 3) == MASK


def test_rotl8_result_stays_in_byte_range() -> None:
    for x in (0, 1, 127, 128, 200, 255):
        for k in range(BITS):
            assert 0 <= rotl8(x, k) <= MASK
